.profile-settings {
  max-width: 640px;
  margin: 0 auto;
  padding: 32px;
}

.profile-settings__title,
.profile-settings__section-title {
  margin: 0;
}

.profile-settings__section {
  display: flex;
  flex-direction: column;
  gap: 16px;
  padding-top: 24px;
  border-top: 1px solid var(--g-color-line-generic);
}

.profile-settings__fieldset {
  margin: 0;
  padding: 24px 0 0;
  border-width: 1px 0 0;
  border-style: solid;
  border-color: var(--g-color-line-generic);
  min-width: 0;
}

/* <legend> внутри fieldset иначе «садится» на верхнюю границу */
.profile-settings__legend {
  float: left;
  width: 100%;
  padding: 0;
  margin-bottom: 16px;
}

.profile-settings__legend + * {
  clear: both;
}

.profile-settings__field {
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.profile-settings__label {
  font-family: var(--g-text-body-font-family);
  font-size: var(--g-text-body-1-font-size);
  line-height: var(--g-text-body-1-line-height);
  font-weight: var(--g-text-accent-font-weight);
  color: var(--g-color-text-primary);
}

.profile-settings__actions {
  padding-top: 24px;
  border-top: 1px solid var(--g-color-line-generic);
}

